3	import java.net.URI;
4	
5	import net.officefloor.plugin.variable.Val;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.http.ResponseEntity;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	
13	public class RespondWithOwnerCreated {
14	
15	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
16	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
17	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
18	        dto.setBulkSignupWarning(BulkSignup.warningFor(ownerRepository));
19	        // A declared household member (created via sharesHousehold) is not a suspected duplicate.
20	        Integer possibleDuplicateOf = PossibleDuplicate.sharesHousehold(owner, ownerRepository)
21	                ? null : PossibleDuplicate.matchFor(owner, ownerRepository);
22	        dto.setPossibleDuplicate(possibleDuplicateOf != null);
23	        dto.setPossibleDuplicateOf(possibleDuplicateOf);
24	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
25	    }
26	}
