1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Period;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
8	
9	/**
10	 * Derives an owner's {@code ageBand} — the coarse age classification returned on the owner DTO.
11	 *
12	 * <p>The band is computed from the owner's {@code birthDate} measured against their
13	 * {@code registrationDate} (the effective, business-day-adjusted date resolved at creation):
14	 * {@code MINOR} when under 18, {@code ADULT} from 18 up to and including 64, {@code SENIOR} at 65 or
15	 * over. When no birth date was supplied the band is absent ({@code null}).
16	 */
17	public final class AgeBand {
18	
19	    private static final int ADULT_AGE = 18;
20	
21	    private static final int SENIOR_AGE = 65;
22	
23	    private AgeBand() {
24	    }
25	
26	    /** The owner's age band, or {@code null} when no birth date is present. */
27	    public static OwnerDto.AgeBandEnum of(Owner owner) {
28	        LocalDate birthDate = owner.getBirthDate();
29	        if (birthDate == null) {
30	            return null;
31	        }
32	        LocalDate reference = owner.getRegistrationDate();
33	        if (reference == null) {
34	            reference = LocalDate.now();
35	        }
36	        int years = Period.between(birthDate, reference).getYears();
37	        if (years < ADULT_AGE) {
38	            return OwnerDto.AgeBandEnum.MINOR;
39	        }
40	        if (years < SENIOR_AGE) {
41	            return OwnerDto.AgeBandEnum.ADULT;
42	        }
43	        return OwnerDto.AgeBandEnum.SENIOR;
44	    }
45	}
