17	public class CheckDailyLimit {
18	
19	    /** Maximum owners that may be created per day; the next create once reached is rejected. */
20	    static final int MAX_PER_DAY = 100;
21	
22	    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
23	            throws DailyLimitExceededException {
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (registrationDate.equals(existing.getRegistrationDate())) {
27	                count++;
28	            }
29	        }
30	        if (count >= MAX_PER_DAY) {
31	            throw new DailyLimitExceededException(count);
32	        }
33	    }
34	}
